DO $late022$ DECLARE owner_oid oid;fn pg_proc%rowtype;BEGIN IF pg_catalog.to_regclass('fsrs_private.admission_settings') IS NULL THEN EXECUTE $late_profile_gate$-- Read-only catalog gate; execute inside the parent transaction with search_path empty.
