  OR EXISTS(SELECT 1 FROM pg_catalog.pg_class WHERE oid=ANY(ARRAY['public.reading_materials'::regclass,'public.uploaded_pdfs'::regclass,'public.user_vocabulary'::regclass,'public.vocabulary_contexts'::regclass,'public.user_known_words'::regclass,'public.review_events'::regclass,'public.vocabulary_exclusions'::regclass]) AND relowner<>owner_oid)
  THEN RAISE EXCEPTION 'fsrs_operator_visibility_not_audited'; END IF;
 SELECT * INTO p FROM pg_catalog.pg_proc WHERE oid='fsrs_private.contract_hash()'::regprocedure;
 IF md5(p.prosrc)<>'b43887acc3619ca718b0912b15f833af' OR p.proowner<>owner_oid OR NOT p.prosecdef OR p.provolatile<>'s' OR p.proconfig IS DISTINCT FROM ARRAY['search_path=""']::text[]
  OR has_function_privilege('anon',p.oid,'EXECUTE') OR has_function_privilege('authenticated',p.oid,'EXECUTE') OR has_function_privilege('service_role',p.oid,'EXECUTE')
  THEN RAISE EXCEPTION 'fsrs_integrity_checker_drift'; END IF;
 IF (SELECT contract_hash FROM fsrs_private.settings) IS DISTINCT FROM fsrs_private.contract_hash() THEN RAISE EXCEPTION 'fsrs_passive_contract_drift'; END IF;
 IF (SELECT enabled FROM fsrs_private.settings) OR EXISTS(SELECT 1 FROM public.fsrs_cards)
  THEN RAISE EXCEPTION 'fsrs_activation_requires_initial_inactive_install'; END IF;
 IF to_regprocedure('public.learning_language_capabilities()') IS NULL THEN RAISE EXCEPTION 'fsrs_korean_contract_required'; END IF;
 SELECT * INTO p FROM pg_catalog.pg_proc WHERE oid='public.learning_language_capabilities()'::regprocedure;
 IF p.proowner<>owner_oid OR p.prosecdef OR p.provolatile<>'s' OR p.proconfig IS DISTINCT FROM ARRAY['search_path=""']::text[]
  OR has_function_privilege('anon',p.oid,'EXECUTE') OR has_function_privilege('service_role',p.oid,'EXECUTE')
  OR NOT has_function_privilege('authenticated',p.oid,'EXECUTE')
  OR EXISTS(SELECT 1 FROM pg_catalog.aclexplode(p.proacl) a WHERE a.grantee NOT IN (owner_oid,(SELECT oid FROM pg_roles WHERE rolname='authenticated')) OR a.is_grantable)
  THEN RAISE EXCEPTION 'fsrs_korean_capability_acl_drift'; END IF;
 body:=p.prosrc;
 IF (SELECT count(*) FROM regexp_matches(body,'ready:=live_hash= ''[0-9a-f]{32}'';','g'))<>1 THEN RAISE EXCEPTION 'fsrs_korean_capability_template_drift'; END IF;
 actual_template:=regexp_replace(body,'ready:=live_hash= ''[0-9a-f]{32}'';','ready:=live_hash= %L;');
 IF actual_template IS DISTINCT FROM $expected$
 DECLARE live_hash text; ready boolean:=false;
 BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'login_required' USING ERRCODE='42501'; END IF;
  WITH RECURSIVE relevant_roles(oid) AS (
 SELECT oid FROM pg_catalog.pg_roles WHERE rolname IN ('authenticated','anon','service_role')
 UNION SELECT m.roleid FROM pg_catalog.pg_auth_members m JOIN relevant_roles r ON r.oid=m.member
), tables AS (
 SELECT c.* FROM pg_catalog.pg_class c WHERE c.relnamespace='public'::pg_catalog.regnamespace
 AND c.relname IN ('user_vocabulary','vocabulary_contexts','user_known_words','vocabulary_exclusions','review_events','reading_materials','uploaded_pdfs','active_vocabulary','vocabulary_with_exclusions')
), objects AS (
 SELECT 'relation:'||c.relname AS key,pg_catalog.jsonb_build_array(c.relkind,c.relrowsecurity,c.relforcerowsecurity,c.relacl,c.reloptions,c.relowner) AS val FROM tables c
 UNION ALL SELECT 'role:'||r.rolname,pg_catalog.jsonb_build_array(r.rolsuper,r.rolbypassrls,r.rolinherit) FROM pg_catalog.pg_roles r JOIN relevant_roles rr ON rr.oid=r.oid
 UNION ALL SELECT 'membership:'||m.member::text||':'||m.roleid::text,pg_catalog.to_jsonb(m) FROM pg_catalog.pg_auth_members m JOIN relevant_roles r ON r.oid=m.member
 UNION ALL SELECT 'schema:'||n.nspname,pg_catalog.jsonb_build_array(n.nspacl,n.nspowner) FROM pg_catalog.pg_namespace n WHERE n.nspname IN ('public','auth')
 UNION ALL SELECT 'constraint:'||c.relname||':'||x.conname,pg_catalog.to_jsonb(pg_catalog.pg_get_constraintdef(x.oid)) FROM pg_catalog.pg_constraint x JOIN tables c ON c.oid=x.conrelid
 UNION ALL SELECT 'index:'||c.relname||':'||i.indexrelid::text,pg_catalog.jsonb_build_array(pg_catalog.pg_get_indexdef(i.indexrelid),i.indisvalid,i.indisready) FROM pg_catalog.pg_index i JOIN tables c ON c.oid=i.indrelid
 UNION ALL SELECT 'policy:'||c.relname||':'||p.polname,pg_catalog.jsonb_build_array(p.polcmd,p.polpermissive,p.polroles,pg_catalog.pg_get_expr(p.polqual,p.polrelid),pg_catalog.pg_get_expr(p.polwithcheck,p.polrelid)) FROM pg_catalog.pg_policy p JOIN tables c ON c.oid=p.polrelid
 UNION ALL SELECT 'trigger:'||c.relname||':'||t.tgname,pg_catalog.jsonb_build_array(pg_catalog.pg_get_triggerdef(t.oid),t.tgenabled) FROM pg_catalog.pg_trigger t JOIN tables c ON c.oid=t.tgrelid WHERE NOT t.tgisinternal
 UNION ALL SELECT 'view:'||c.relname,pg_catalog.to_jsonb(pg_catalog.pg_get_viewdef(c.oid,true)) FROM tables c WHERE c.relkind='v'
 UNION ALL SELECT 'column:'||c.relname||':'||a.attname,pg_catalog.jsonb_build_array(a.atttypid,a.atttypmod,a.attnotnull,a.attacl,a.attidentity,a.attgenerated,pg_catalog.pg_get_expr(d.adbin,d.adrelid)) FROM pg_catalog.pg_attribute a JOIN tables c ON c.oid=a.attrelid LEFT JOIN pg_catalog.pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attnum>0 AND NOT a.attisdropped
 UNION ALL SELECT 'function:'||p.oid::text,pg_catalog.jsonb_build_array(pg_catalog.pg_get_functiondef(p.oid),p.proacl,p.proowner) FROM pg_catalog.pg_proc p WHERE p.oid IN (
 SELECT pg_catalog.to_regprocedure(f.signature) FROM (VALUES ('public.save_vocabulary_context(jsonb,jsonb,uuid,text)'),('public.set_vocabulary_exclusion(text,text,uuid,boolean,uuid)'),('public.lock_vocabulary_exclusion_owner()'),('public.preserve_deleted_vocabulary_exclusion()'),('public.guard_excluded_vocabulary()'),('public.guard_excluded_review_event()'),('public.sync_vocabulary_exclusion_identity()'),('public.sync_known_word_review_exclusion()'),('public.guard_known_word_review_exclusion()')) f(signature)
 UNION SELECT dependency.oid FROM (VALUES ('public.save_vocabulary_context(jsonb,jsonb,uuid,text)'),('public.save_vocabulary_context_for(uuid,jsonb,jsonb,uuid,text)'),('public.viewer_replace_analysis(bigint,text,jsonb,text,jsonb,uuid)'),('public.viewer_undo_vocabulary_save(uuid,jsonb,uuid[])'),('public.classroom_save_vocabulary(uuid,bigint,integer,bigint,text,jsonb,jsonb,jsonb,jsonb,uuid,text)'),('library_private.protect_source_delete()'),('public.guard_source_passage_write()'),('public.library_book_preserve_metadata()'),('public.validate_source_passage()'),('public.protect_composer_source()')) f(signature)
 JOIN pg_catalog.pg_proc dependency ON dependency.oid::pg_catalog.regprocedure::text=f.signature
 UNION SELECT t.tgfoid FROM pg_catalog.pg_trigger t JOIN tables c ON c.oid=t.tgrelid WHERE NOT t.tgisinternal)
) SELECT pg_catalog.md5(pg_catalog.jsonb_object_agg(key,val ORDER BY key)::text) FROM objects INTO live_hash;
  ready:=live_hash= %L;
  RETURN pg_catalog.jsonb_build_object('version',1,'languages',pg_catalog.jsonb_build_object('Korean',
   pg_catalog.jsonb_build_object('save',ready,'review',ready,'known',ready,'exclude',ready)));
 END $expected$ THEN RAISE EXCEPTION 'fsrs_korean_capability_template_drift'; END IF;
 -- Validate the manager-only context and public capability contract without calling the login-protected API.
 PERFORM pg_temp.management_korean_capabilities();
 ready:=(pg_temp.management_korean_capabilities()#>>'{languages,Korean,save}')::boolean;
 IF ready IS DISTINCT FROM true THEN RAISE EXCEPTION 'fsrs_existing_korean_contract_not_ready'; END IF;
 SELECT * INTO p FROM pg_catalog.pg_proc WHERE oid='fsrs_private.guard_legacy_vocabulary()'::regprocedure;
 IF p.proowner<>owner_oid OR NOT p.prosecdef OR p.proconfig IS DISTINCT FROM ARRAY['search_path=""']::text[] OR md5(p.prosrc)<>'712ee0b0c87fba26bc699009accc6b15'
  OR has_function_privilege('anon',p.oid,'EXECUTE') OR has_function_privilege('authenticated',p.oid,'EXECUTE') OR has_function_privilege('service_role',p.oid,'EXECUTE')
  THEN RAISE EXCEPTION 'fsrs_guard_definition_drift'; END IF;
SELECT * INTO p FROM pg_catalog.pg_proc WHERE oid='fsrs_private.guard_legacy_event()'::regprocedure;
 IF p.proowner<>owner_oid OR NOT p.prosecdef OR p.proconfig IS DISTINCT FROM ARRAY['search_path=""']::text[] OR md5(p.prosrc)<>'93dae088671147055b906af20f2aeacd'
  OR has_function_privilege('anon',p.oid,'EXECUTE') OR has_function_privilege('authenticated',p.oid,'EXECUTE') OR has_function_privilege('service_role',p.oid,'EXECUTE')
  THEN RAISE EXCEPTION 'fsrs_guard_definition_drift'; END IF;
 INSERT INTO pg_temp.fsrs_activation_state VALUES(pg_temp.fsrs_catalog(),pg_get_functiondef('public.learning_language_capabilities()'::regprocedure),body,ready);
END $preflight$;
CREATE TRIGGER fsrs_guard_legacy_vocabulary BEFORE UPDATE OR DELETE ON public.user_vocabulary FOR EACH ROW EXECUTE FUNCTION fsrs_private.guard_legacy_vocabulary();
CREATE TRIGGER fsrs_guard_legacy_event BEFORE INSERT OR UPDATE OR DELETE ON public.review_events FOR EACH ROW EXECUTE FUNCTION fsrs_private.guard_legacy_event();
DO $successor$
DECLARE prior jsonb; after_catalog jsonb; reduced jsonb; definition text; old_source text; new_hash text; changed text[]; expected_keys text[];
BEGIN
 SELECT before_catalog,before_function,before_source INTO prior,definition,old_source FROM pg_temp.fsrs_activation_state;
 after_catalog:=pg_temp.fsrs_catalog();
 expected_keys:=ARRAY['trigger:user_vocabulary:fsrs_guard_legacy_vocabulary','trigger:review_events:fsrs_guard_legacy_event',
  'function:'||'fsrs_private.guard_legacy_vocabulary()'::regprocedure::oid::text,'function:'||'fsrs_private.guard_legacy_event()'::regprocedure::oid::text];
 SELECT array_agg(key ORDER BY key) INTO changed FROM (SELECT key FROM jsonb_each(after_catalog) WHERE prior->key IS DISTINCT FROM value
  UNION SELECT key FROM jsonb_each(prior) WHERE NOT after_catalog ? key) differences;
 IF (SELECT array_agg(x ORDER BY x) FROM unnest(expected_keys) x) IS DISTINCT FROM changed OR (after_catalog-expected_keys) IS DISTINCT FROM prior
  THEN RAISE EXCEPTION 'fsrs_unreviewed_catalog_delta'; END IF;
 IF (SELECT count(*) FROM pg_trigger WHERE (tgname,tgrelid,tgfoid,tgtype) IN
  (('fsrs_guard_legacy_vocabulary','public.user_vocabulary'::regclass,'fsrs_private.guard_legacy_vocabulary()'::regprocedure,27),
   ('fsrs_guard_legacy_event','public.review_events'::regclass,'fsrs_private.guard_legacy_event()'::regprocedure,31))
  AND tgenabled='O' AND tgqual IS NULL AND tgnargs=0 AND tgattr=''::int2vector AND NOT tgisinternal)<>2
  THEN RAISE EXCEPTION 'fsrs_unreviewed_guard_trigger'; END IF;
 new_hash:=md5(after_catalog::text);
 definition:=regexp_replace(definition,'ready:=live_hash= ''[0-9a-f]{32}'';','ready:=live_hash= '||quote_literal(new_hash)||';');
 EXECUTE definition;
 IF regexp_replace((SELECT prosrc FROM pg_proc WHERE oid='public.learning_language_capabilities()'::regprocedure),'ready:=live_hash= ''[0-9a-f]{32}'';','ready:=live_hash= %L;')
  IS DISTINCT FROM regexp_replace(old_source,'ready:=live_hash= ''[0-9a-f]{32}'';','ready:=live_hash= %L;')
  OR pg_temp.fsrs_catalog() IS DISTINCT FROM after_catalog
  THEN RAISE EXCEPTION 'fsrs_successor_changed_unreviewed_catalog'; END IF;
 IF (pg_temp.management_korean_capabilities()#>>'{languages,Korean,save}')::boolean IS DISTINCT FROM true
  THEN RAISE EXCEPTION 'fsrs_successor_korean_not_ready'; END IF;
 IF EXISTS((SELECT * FROM public.reading_materials EXCEPT ALL SELECT * FROM pg_temp.fsrs_preserve_reading_materials) UNION ALL (SELECT * FROM pg_temp.fsrs_preserve_reading_materials EXCEPT ALL SELECT * FROM public.reading_materials)) THEN RAISE EXCEPTION 'fsrs_preservation_failed: reading_materials'; END IF;
IF EXISTS((SELECT * FROM public.uploaded_pdfs EXCEPT ALL SELECT * FROM pg_temp.fsrs_preserve_uploaded_pdfs) UNION ALL (SELECT * FROM pg_temp.fsrs_preserve_uploaded_pdfs EXCEPT ALL SELECT * FROM public.uploaded_pdfs)) THEN RAISE EXCEPTION 'fsrs_preservation_failed: uploaded_pdfs'; END IF;
IF EXISTS((SELECT * FROM public.user_vocabulary EXCEPT ALL SELECT * FROM pg_temp.fsrs_preserve_user_vocabulary) UNION ALL (SELECT * FROM pg_temp.fsrs_preserve_user_vocabulary EXCEPT ALL SELECT * FROM public.user_vocabulary)) THEN RAISE EXCEPTION 'fsrs_preservation_failed: user_vocabulary'; END IF;
IF EXISTS((SELECT * FROM public.vocabulary_contexts EXCEPT ALL SELECT * FROM pg_temp.fsrs_preserve_vocabulary_contexts) UNION ALL (SELECT * FROM pg_temp.fsrs_preserve_vocabulary_contexts EXCEPT ALL SELECT * FROM public.vocabulary_contexts)) THEN RAISE EXCEPTION 'fsrs_preservation_failed: vocabulary_contexts'; END IF;
IF EXISTS((SELECT * FROM public.user_known_words EXCEPT ALL SELECT * FROM pg_temp.fsrs_preserve_user_known_words) UNION ALL (SELECT * FROM pg_temp.fsrs_preserve_user_known_words EXCEPT ALL SELECT * FROM public.user_known_words)) THEN RAISE EXCEPTION 'fsrs_preservation_failed: user_known_words'; END IF;
IF EXISTS((SELECT * FROM public.review_events EXCEPT ALL SELECT * FROM pg_temp.fsrs_preserve_review_events) UNION ALL (SELECT * FROM pg_temp.fsrs_preserve_review_events EXCEPT ALL SELECT * FROM public.review_events)) THEN RAISE EXCEPTION 'fsrs_preservation_failed: review_events'; END IF;
IF EXISTS((SELECT * FROM public.vocabulary_exclusions EXCEPT ALL SELECT * FROM pg_temp.fsrs_preserve_vocabulary_exclusions) UNION ALL (SELECT * FROM pg_temp.fsrs_preserve_vocabulary_exclusions EXCEPT ALL SELECT * FROM public.vocabulary_exclusions)) THEN RAISE EXCEPTION 'fsrs_preservation_failed: vocabulary_exclusions'; END IF;
 UPDATE fsrs_private.settings SET enabled=true,activated_at=clock_timestamp(),contract_hash=fsrs_private.contract_hash() WHERE singleton;
END $successor$;

